import { applyReleaseSigning } from './withReleaseSigning';

// Shape of android/app/build.gradle as generated by `expo prebuild` (Expo SDK 58 template).
const TEMPLATE = `apply plugin: "com.android.application"

android {
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            minifyEnabled enableMinifyInReleaseBuilds
        }
    }
}
`;

describe('applyReleaseSigning', () => {
  const result = applyReleaseSigning(TEMPLATE);

  it('declares the flag before the android block', () => {
    expect(result.indexOf('def kcalReleaseSigning')).toBeGreaterThan(-1);
    expect(result.indexOf('def kcalReleaseSigning')).toBeLessThan(result.indexOf('android {'));
    for (const name of ['KCAL_UPLOAD_STORE_FILE', 'KCAL_UPLOAD_STORE_PASSWORD', 'KCAL_UPLOAD_KEY_ALIAS', 'KCAL_UPLOAD_KEY_PASSWORD']) {
      expect(result).toContain(`'${name}'`);
    }
  });

  it('adds a release signing config next to the debug one', () => {
    expect(result).toMatch(/signingConfigs \{[\s\S]*release \{[\s\S]*storeFile file\(System\.getenv\('KCAL_UPLOAD_STORE_FILE'\)\)[\s\S]*debug \{/);
  });

  it('signs release builds with it and keeps debug builds on the debug key', () => {
    expect(result).toMatch(/release \{[^}]*signingConfig kcalReleaseSigning \? signingConfigs\.release : signingConfigs\.debug/);
    expect(result).toMatch(/debug \{\s*signingConfig signingConfigs\.debug\s*\}/);
  });

  it('is idempotent', () => {
    expect(applyReleaseSigning(result)).toBe(result);
  });

  it('fails on an unexpected layout instead of silently using debug signing', () => {
    expect(() => applyReleaseSigning('android {\n}\n')).toThrow(/unexpected layout/);
  });
});
